const BASE_URL = (process.env.REACT_APP_API_URL || '/api').replace(/\/$/, '');

async function request(method, path, body, config = {}) {
  const token = localStorage.getItem('df_token');
  const isForm = typeof FormData !== 'undefined' && body instanceof FormData;

  const headers = { ...(config.headers || {}) };
  // مع FormData يجب أن يضع المتصفح Content-Type بنفسه (مع boundary)
  if (isForm) {
    delete headers['Content-Type'];
    delete headers['content-type'];
  } else if (body !== undefined && !headers['Content-Type']) {
    headers['Content-Type'] = 'application/json';
  }
  if (token) headers.Authorization = `Bearer ${token}`;

  let url = `${BASE_URL}${path}`;
  if (config.params) {
    const qs = new URLSearchParams(config.params).toString();
    if (qs) url += (url.includes('?') ? '&' : '?') + qs;
  }

  const res = await fetch(url, {
    method,
    headers,
    body: body === undefined ? undefined : isForm ? body : JSON.stringify(body),
  });

  const wantsBlob = config.responseType === 'blob';

  if (!res.ok) {
    const text = await res.text();
    let data;
    try {
      data = text ? JSON.parse(text) : null;
    } catch {
      data = text;
    }
    const detail = data && (data.detail || data.message);
    const error = new Error(
      typeof detail === 'string' ? detail : `HTTP ${res.status}`,
    );
    error.response = { status: res.status, data };
    throw error;
  }

  if (wantsBlob) {
    return { data: await res.blob(), status: res.status, headers: res.headers };
  }

  const text = await res.text();
  let data;
  try {
    data = text ? JSON.parse(text) : null;
  } catch {
    data = text;
  }
  return { data, status: res.status, headers: res.headers };
}

const api = {
  get: (path, config) => request('GET', path, undefined, config),
  post: (path, body, config) => request('POST', path, body, config),
  put: (path, body, config) => request('PUT', path, body, config),
  patch: (path, body, config) => request('PATCH', path, body, config),
  delete: (path, config) => request('DELETE', path, undefined, config),
};

export { api };
export default api;
